package br.com.ziipsan.core.cutoff;

import java.time.OffsetDateTime;

/**
 * Reconnection generated by the payment (P3.4): {@code rec.auto_order_on_payment}
 * (class b, factory default yes) and {@code rec.release_condition}
 * (class b). Pure.
 *
 * <p>Fee rule of the v1 case: when the cutoff notice had NO delivery
 * proof, the reconnection is WITHOUT fee (Lei 13.460/2017, art. 6º,
 * parágrafo único — "sem prova, religação sem taxa"); an undue cutoff
 * also waives the fee. Otherwise the fee is charged (the charge posting
 * itself is billing's, ED-34 frontier).
 *
 * <p>The SLA deadline is payment instant + the hours of
 * {@code rec.sla_hours} for the reconnection kind (normal, urgent when
 * the user bought urgency, undue when the cutoff was undue).
 */
public final class ReconnectionRule {

    private ReconnectionRule() {
    }

    /** Payment facts, from billing (P2.5) and the cutoff record. */
    public record PaymentFacts(
            boolean motivatingDebtPaidOrAgreed,
            boolean downPaymentPaid,
            boolean fullSettlement,
            boolean urgentRequested,
            boolean cutoffWasUndue,
            CutoffEnums.DeliveryProofStatus noticeProofStatus) {
    }

    public record Decision(
            boolean createOrder,
            String blockedReason,
            CutoffEnums.ReleaseCondition appliedCondition,
            CutoffEnums.FeeDecision feeDecision,
            OffsetDateTime slaDueAt) {
    }

    /** Whether the payment facts satisfy the release condition. */
    public static boolean conditionMet(CutoffEnums.ReleaseCondition condition, PaymentFacts facts) {
        return switch (condition) {
            case MOTIVATING_DEBT_PAID_OR_AGREED -> facts.motivatingDebtPaidOrAgreed();
            case DOWN_PAYMENT_PAID -> facts.downPaymentPaid();
            case FULL_SETTLEMENT -> facts.fullSettlement();
        };
    }

    public static Decision evaluate(PaymentFacts facts, CutoffParameters.Values params,
            OffsetDateTime paymentAt) {
        if (facts == null || params == null || paymentAt == null) {
            throw new IllegalArgumentException("pagamento, parametros e instante sao obrigatorios");
        }
        if (!params.autoOrderOnPayment()) {
            return new Decision(false, "AUTO_ORDER_DISABLED", params.releaseCondition(), null, null);
        }
        CutoffEnums.ReleaseCondition condition = params.releaseCondition();
        if (!conditionMet(condition, facts)) {
            return new Decision(false, "RELEASE_CONDITION_NOT_MET", condition, null, null);
        }
        CutoffEnums.FeeDecision fee = facts.cutoffWasUndue()
                ? CutoffEnums.FeeDecision.WAIVED_UNDUE_CUT
                : facts.noticeProofStatus() != CutoffEnums.DeliveryProofStatus.DELIVERED
                        ? CutoffEnums.FeeDecision.WAIVED_NO_PROOF
                        : CutoffEnums.FeeDecision.CHARGED;
        if (params.slaHours() == null) {
            throw new IllegalStateException("rec.sla_hours sem valor aceito: o prazo da religacao"
                    + " nao e calculado sem o parametro da ERI/tenant.");
        }
        int hours = params.slaHours().hoursFor(facts.urgentRequested(), facts.cutoffWasUndue());
        return new Decision(true, null, condition, fee, paymentAt.plusHours(hours));
    }

    /** Late when completion happened after the SLA deadline; no completion is not yet late-proven. */
    public static boolean isLate(OffsetDateTime slaDueAt, OffsetDateTime completedAt) {
        if (slaDueAt == null) {
            throw new IllegalArgumentException("prazo da religacao e obrigatorio");
        }
        return completedAt != null && completedAt.isAfter(slaDueAt);
    }
}
